#include <stdio.h>
#include <stdlib.h>
int main(void) {
 size_t count = 5;
 int *values = malloc(count * sizeof *values);
 if (values == NULL) return 1;
 for (size_t i=0; i<count; ++i) values[i] = (int)(i * 10);
 for (size_t i=0; i<count; ++i) printf("%d ", values[i]);
 putchar('\n');
 free(values);
 return 0;
}
